/**
 * issue #98: the one project-owned Node-RED node exposing the #89/#91
 * generic durable-Signal-wait primitive to flow authors.
 *
 * All actual suspend/resume behavior lives Activity-side, in
 * `lib/signalSuspensionAdapter.js` (composed into the default runner via
 * `lib/defaultSuspensionAdapter.js`) - this file is deliberately thin:
 *   - no process-local timer;
 *   - no external socket/server;
 *   - no @temporalio/* import;
 *   - Workflow code (workflows.js) remains completely unaware this node
 *     type exists.
 *
 * `on("input")` below only ever runs when this node is invoked WITHOUT a
 * suspension adapter installed (e.g. a stock Node-RED instance not using
 * this runtime's Activity/Worker wiring at all) - the default runner
 * always installs a suspension adapter that suspends every valid
 * invocation of this node type BEFORE `node.receive()` is ever called (see
 * `activities.js`), so in normal operation this handler is dead code. It
 * exists only as a documented, safe fallback: pass the message through
 * unchanged rather than silently swallowing it.
 */

module.exports = function(RED) {
    "use strict";

    function TemporalSignalWaitNode(config) {
        RED.nodes.createNode(this, config);
        this.keyProperty = (config.keyProperty && String(config.keyProperty).trim().length > 0)
            ? String(config.keyProperty).trim()
            : "waitKey";

        this.on("input", function(msg, send, done) {
            send = send || function() { this.send.apply(this, arguments); }.bind(this);
            send(msg);
            if (done) {
                done();
            }
        });
    }

    RED.nodes.registerType("temporal signal wait", TemporalSignalWaitNode);
};
